args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?dir ?dirLabel ?birthDate WHERE {
  VALUES ?film { dbr:Dhuen_Ki_Lakeer dbr:Night_of_the_Twelve }
  ?film dbo:director ?dir .
  ?dir dbo:birthDate ?birthDate .
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(langMatches(lang(?filmLabel), "en")) }
  OPTIONAL { ?dir rdfs:label ?dirLabel FILTER(langMatches(lang(?dirLabel), "en")) }
}
ORDER BY ?birthDate
LIMIT 1

